                    roundScore = Math.round(actionInfo.impact * effectivenessMultiplier * Math.min(budgetEfficiency, 1.2));
                    ds.actionScore += roundScore;

                    var ebitdaImpact = roundScore / 50;
                    ds.ebitdaRecovery = Math.min(ds.ebitdaRecovery + ebitdaImpact, 100);

                    finding = 'finding_action';
                }
            } else {
                timeCost = this.APPROACH_TIME[d.approach] || 10;
                var outOfTime = timeCost > ds.timeRemaining; // can't afford -> forced no-op round
                ds.timeRemaining = Math.max(0, ds.timeRemaining - timeCost);

                if (ds.visitedModules.indexOf(d.module) === -1) {
                    ds.visitedModules.push(d.module);
                }
                var prevDepth = ds.moduleBestDepth[d.module] || 0;

                // Compute discovery with the PRIOR best depth so the first visit at a given
                // depth earns full gains and only genuine re-visits are diminished. The
                // moduleBestDepth update is deliberately performed AFTER this call. (It used
                // to run before, so _calculateDiscovery always saw prevDepth >= approach and
                // cut every analysis to 30% -> no root cause could ever reach 70 and the sim
                // was unwinnable.)
                var discoveryGains = outOfTime
                    ? { a: 0, b: 0, c: 0 }
                    : this._calculateDiscovery(d.module, d.approach, ds);

                if (d.approach > prevDepth) {
                    ds.moduleBestDepth[d.module] = d.approach;
                }

                ds.rootCauseA = Math.min(100, ds.rootCauseA + discoveryGains.a);
                ds.rootCauseB = Math.min(100, ds.rootCauseB + discoveryGains.b);
                ds.rootCauseC = Math.min(100, ds.rootCauseC + discoveryGains.c);

                var newCausesFound = 0;
                if (ds.rootCauseA >= 70) newCausesFound++;
                if (ds.rootCauseB >= 70) newCausesFound++;
                if (ds.rootCauseC >= 70) newCausesFound++;
                ds.causesFound = newCausesFound;

                roundScore = discoveryGains.a + discoveryGains.b + discoveryGains.c;
                roundScore += (d.approach - 1) * 3;
                if (ds.visitedModules.length >= 3) roundScore += 5;

                var findingKey = d.module + '_' + d.approach;
                finding = outOfTime ? 'finding_out_of_time'
                                    : (this.FINDINGS_MAP[findingKey] || 'finding_default');
            }

            if (!isActionPhase) ds.analyticalScore += roundScore; // action score lives in actionScore only (was double-counted into totalScore during the action phase)
            ds.totalScore = ds.analyticalScore + ds.actionScore;
            ds.lastFinding = finding;

            // platform score: same causesFound plus totalScore verdict bands getPerformanceSummary
            // uses (Developing / Competent / Proficient / Excellent), mapped to representative
            // 0-100 values so the platform score band always matches the final verdict band
            var scoreBand = 15;
            if (ds.causesFound >= 3 && ds.totalScore > 200) scoreBand = 90;
            else if (ds.causesFound >= 2 && ds.totalScore > 120) scoreBand = 70;
            else if (ds.causesFound >= 1 && ds.totalScore > 60) scoreBand = 45;
            var overallScore = Math.max(0, Math.min(100, scoreBand));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            ds.scoreHistory.push(ds.totalScore);
            ds.causeAHistory.push(ds.rootCauseA);
            ds.causeBHistory.push(ds.rootCauseB);
            ds.causeCHistory.push(ds.rootCauseC);

            this._updateProgressBars(ds);

            var findingsEl = document.getElementById('findingsText');
            if (findingsEl) {
                findingsEl.innerHTML = window.mySimulation.t(finding);
            }

            return {
                period: period,
                module: d.module,
                approach: d.approach,
                action: d.action,
                budget: d.budget,
                timeCost: timeCost,
                timeRemaining: ds.timeRemaining,
                roundScore: roundScore,
                totalScore: ds.totalScore,
                rootCauseA: ds.rootCauseA,
                rootCauseB: ds.rootCauseB,
                rootCauseC: ds.rootCauseC,
                causesFound: ds.causesFound,
                ebitdaRecovery: ds.ebitdaRecovery
            };
        }

        _calculateDiscovery(module, approach, ds) {
            var a = 0, b = 0, c = 0;
            var hasVisitedCommercial = ds.visitedModules.indexOf(2) !== -1;
            var hasVisitedFinancial = ds.visitedModules.indexOf(5) !== -1;
            var crossRefBonus = (hasVisitedCommercial && hasVisitedFinancial) ? 1.3 : 1.0;

            if (module === 1) {
                if (approach === 1) { a = 8; }
                if (approach === 2) { a = 14; b = 5; }
                if (approach === 3) { a = 18; b = 8; c = 3; }
            } else if (module === 2) {
                if (approach === 1) { b = 6; }
                if (approach === 2) { b = 10; c = 12; }
                if (approach === 3) { b = 14; c = Math.round(22 * crossRefBonus); }
            } else if (module === 3) {
                if (approach === 1) { a = 18; }
                if (approach === 2) { a = 35; }
                if (approach === 3) { a = 45; b = 5; }
            } else if (module === 4) {
                if (approach === 1) { a = 2; b = 2; c = 2; }
                if (approach === 2) { a = 3; b = 3; c = 3; }
                if (approach === 3) { a = 5; b = 5; c = 5; }
            } else if (module === 5) {
                if (approach === 1) { a = 8; b = 8; }
                if (approach === 2) { b = 18; c = 10; }
                if (approach === 3) { b = 25; c = Math.round(28 * crossRefBonus); }
            }

            var prevDepth = ds.moduleBestDepth[module] || 0;
            if (prevDepth >= approach) {
                var diminish = 0.3;
                a = Math.round(a * diminish);
                b = Math.round(b * diminish);
                c = Math.round(c * diminish);
            }

            return { a: a, b: b, c: c };
        }

        _updateProgressBars(ds) {
            var barA = document.getElementById('causeABar');
            var barB = document.getElementById('causeBBar');
            var barC = document.getElementById('causeCBar');
            if (barA) { barA.style.width = ds.rootCauseA + '%'; barA.textContent = ds.rootCauseA + '%'; }
            if (barB) { barB.style.width = ds.rootCauseB + '%'; barB.textContent = ds.rootCauseB + '%'; }
            if (barC) { barC.style.width = ds.rootCauseC + '%'; barC.textContent = ds.rootCauseC + '%'; }
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var isActionPhase = period >= 7;

            var invControls = document.getElementById('investigationControls');
            var actControls = document.getElementById('actionControls');
            if (invControls) invControls.style.display = isActionPhase ? 'none' : 'block';
            if (actControls) actControls.style.display = isActionPhase ? 'block' : 'none';

            var phaseEl = document.getElementById('phaseTitle');
            var briefEl = document.getElementById('briefingText');

            if (period <= 2) {
                if (phaseEl) phaseEl.textContent = window.mySimulation ? window.mySimulation.t('phase_explore_title') : 'Phase 1: Exploration';
                if (briefEl) briefEl.innerHTML = window.mySimulation ? (window.mySimulation.t('briefing_initial') + '<br><br>' + window.mySimulation.t('phase_explore_text')) : '';
            } else if (period <= 4) {
                if (phaseEl) phaseEl.textContent = window.mySimulation ? window.mySimulation.t('phase_diagnose_title') : 'Phase 2: Diagnostic';
                if (briefEl) briefEl.innerHTML = window.mySimulation ? window.mySimulation.t('phase_diagnose_text') : '';
            } else if (period <= 6) {
                if (phaseEl) phaseEl.textContent = window.mySimulation ? window.mySimulation.t('phase_deep_title') : 'Phase 3: Deep Analysis';
                if (briefEl) briefEl.innerHTML = window.mySimulation ? window.mySimulation.t('phase_deep_text') : '';
            } else {
                if (phaseEl) phaseEl.textContent = window.mySimulation ? window.mySimulation.t('phase_action_title') : 'Phase 4: Corrective Actions';
                if (briefEl) briefEl.innerHTML = window.mySimulation ? window.mySimulation.t('phase_action_text') : '';
            }

            if (state.domainState) {
                this._updateProgressBars(state.domainState);
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('timeDisplay', 'domainState.timeRemaining', function(v) { return v + ' min'; });
            uiManager.bind('scoreDisplay', 'domainState.totalScore');
            uiManager.bind('causesDisplay', 'domainState.causesFound', function(v) { return v + ' / 3'; });
            uiManager.bind('ebitdaDisplay', 'domainState.ebitdaRecovery', function(v) { return Math.round(v) + '%'; });
            this._wireEvents();
        }

        _wireEvents() {
            if (this._eventsWired) return;
            this._eventsWired = true;
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                // Render briefing/controls for the LIVE period after each submit. The
                // framework has already advanced currentPeriod, so we render for it
                // directly (no +1). Replaces the old setTimeout that rendered one period
                // ahead and flipped to the action phase a round early.
                sim.eventBus.on('period:submitted', function() { self._renderLive(); });
                // On undo, if history is now empty, restore the documented defaults, then
                // re-render KPIs, progress bars and the briefing for the restored period.
                sim.eventBus.on('period:undone', function(state) {
                    if (state && (!state.history || state.history.length === 0)) {
                        self._resetDomainState(state);
                    }
                    self._renderLive();
                });
            }
            // Re-localize the dynamic briefing + last finding when the language changes.
            document.addEventListener('express:langchanged', function() { self._renderLive(); });
        }

        _renderLive() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            this._updateBriefing(sim.state);
            var findingsEl = document.getElementById('findingsText');
            if (findingsEl && sim.state.domainState && sim.state.domainState.lastFinding) {
                findingsEl.innerHTML = sim.t(sim.state.domainState.lastFinding);
            }
        }

        _resetDomainState(state) {
            state.domainState = {
                timeRemaining: 90,
                rootCauseA: 0, rootCauseB: 0, rootCauseC: 0,
                causesFound: 0, analyticalScore: 0, actionScore: 0,
                ebitdaRecovery: 0, totalScore: 0,
                visitedModules: [], moduleBestDepth: {},
                selectedActions: [], budgetUsed: 0, lastFinding: '',
                scoreHistory: [], causeAHistory: [], causeBHistory: [], causeCHistory: []
            };
            if (window.mySimulation && typeof window.mySimulation.updateUI === 'function') {
                window.mySimulation.updateUI();
            }
            this._updateProgressBars(state.domainState);
            var findingsEl = document.getElementById('findingsText');
            if (findingsEl) findingsEl.innerHTML = '';
        }

        formatCompletionMessage(summary) {
            var sim = window.mySimulation;
            var t = function(k) { return sim ? sim.t(k) : k; };
            var causes = summary.causesFound || 0;
            var score  = summary.totalScore || 0;
            var ebitda = Math.round(summary.ebitdaRecovery || 0);
            var perfKey = 'perf_developing';
            if (causes >= 3 && score > 200) perfKey = 'perf_excellent';
            else if (causes >= 2 && score > 120) perfKey = 'perf_proficient';
            else if (causes >= 1 && score > 60) perfKey = 'perf_competent';
            var insights = [];
            if (causes === 3) insights.push(t('insight_causes_3'));
            else if (causes === 2) insights.push(t('insight_causes_2'));
            else if (causes === 1) insights.push(t('insight_causes_1'));
            else insights.push(t('insight_causes_0'));
            if (ebitda > 60) insights.push(t('insight_ebitda_high'));
            else if (ebitda > 30) insights.push(t('insight_ebitda_mid'));
            else insights.push(t('insight_ebitda_low'));
            var insHtml = insights.map(function(s) { return '<li style="margin-bottom:6px;">' + s + '</li>'; }).join('');
            return '' +
              '<div style="background:linear-gradient(135deg,#1a3a5c 0%,#2c5f8a 100%);color:#fff;border-radius:14px;padding:24px;text-align:center;">' +
                '<div style="font-size:0.75rem;letter-spacing:1px;opacity:0.75;text-transform:uppercase;">' + t('completion_performance') + '</div>' +
                '<div style="font-size:1.7rem;font-weight:700;margin:6px 0 18px;">' + t(perfKey) + '</div>' +
                '<div style="display:flex;justify-content:center;gap:26px;flex-wrap:wrap;">' +
                  '<div><div style="font-size:1.6rem;font-weight:700;">' + causes + ' / 3</div><div style="font-size:0.74rem;opacity:0.85;">' + t('completion_causes') + '</div></div>' +
                  '<div><div style="font-size:1.6rem;font-weight:700;">' + score + '</div><div style="font-size:0.74rem;opacity:0.85;">' + t('completion_score') + '</div></div>' +
                  '<div><div style="font-size:1.6rem;font-weight:700;">' + ebitda + '%</div><div style="font-size:0.74rem;opacity:0.85;">' + t('completion_ebitda') + '</div></div>' +
                '</div>' +
              '</div>' +
              '<div style="margin-top:16px;">' +
                '<h5 style="margin-bottom:10px;">' + t('completion_insights') + '</h5>' +
                '<ul style="text-align:left;padding-left:20px;margin:0;">' + insHtml + '</ul>' +
              '</div>';
        }

